days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "through":
        a, b = nums[0], nums[1]
        print(f"  count: {b} - ({a}) + 1 = {b - a + 1}")
    elif kind == "signs":
        a, b = nums[0], nums[1]
        size = abs(a) * abs(b)
        if a == 0 or b == 0:
            print("  a zero factor, so 0")
        elif (a < 0) == (b < 0):
            print(f"  sizes {abs(a)} * {abs(b)} = {size}, signs same, so {size}")
        else:
            print(f"  sizes {abs(a)} * {abs(b)} = {size}, signs differ, so {-size}")
    elif kind == "remainder":
        a, b = nums[0], nums[1]
        print(f"  {a} = {b} * {a // b} + {a % b}")
    elif kind == "prime":
        n = nums[0]
        d = 2
        while d * d <= n and n % d != 0:
            d = d + 1
        if n < 2:
            print(f"  {n} is neither prime nor composite")
        elif d * d <= n:
            print(f"  {n} = {d} * {n // d}, composite")
        else:
            print(f"  {n} is prime")
    elif kind == "gcd":
        a, b = nums[0], nums[1]
        steps = 0
        while b != 0:
            a, b = b, a % b
            steps = steps + 1
        print(f"  gcd = {a} after {steps} steps")
    elif kind == "day":
        start, t = nums[0], nums[1]
        total = start + t
        print(f"  {start} + ({t}) = {total} = 7 * {total // 7} + {total % 7}, {days[total % 7]}")

import math

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "boxes":
        items, size = nums[0], nums[1]
        q, r = items // size, items % size
        boxes = q
        if r > 0:
            boxes = q + 1
        print(f"  {items} = {size} * {q} + {r}, boxes needed: {boxes}")
    elif kind == "tiles":
        w, h = nums[0], nums[1]
        g = math.gcd(w, h)
        print(f"  side {g}, {w // g} * {h // g} = {(w // g) * (h // g)} tiles")
    elif kind == "together":
        print(f"  together every {math.lcm(nums[0], nums[1])}")
    elif kind == "clock":
        shows = (nums[0] + nums[1]) % 12
        if shows == 0:
            shows = 12
        print(f"  the clock shows {shows}")
    elif kind == "change":
        c = nums[1] - nums[0]
        if c > 0:
            print(f"  rose by {c}")
        elif c < 0:
            print(f"  fell by {-c}")
        else:
            print("  no change")
    elif kind == "posts":
        start, end = nums[0], nums[1]
        print(f"  length {end - start}, posts {end - start + 1}")

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "bezout":
        a, b = nums[0], nums[1]
        r0, r1, x0, x1, y0, y1 = a, b, 1, 0, 0, 1
        while r1 != 0:
            q = r0 // r1
            r0, r1 = r1, r0 - q * r1
            x0, x1 = x1, x0 - q * x1
            y0, y1 = y1, y0 - q * y1
        print(f"  {a} * {x0} + {b} * {y0} = {r0}")
    elif kind == "factor":
        n = nums[0]
        start = n
        text = ""
        d = 2
        while d * d <= n:
            e = 0
            while n % d == 0:
                n = n // d
                e = e + 1
            if e > 0:
                piece = f"{d}"
                if e > 1:
                    piece = f"{d}^{e}"
                if text == "":
                    text = piece
                else:
                    text = f"{text} * {piece}"
            d = d + 1
        if n > 1 and text == "":
            text = f"{n}"
        elif n > 1:
            text = f"{text} * {n}"
        print(f"  {start} = {text}")
    elif kind == "isbn":
        s = 0
        for t in range(9):
            s = s + (nums[0] // 10 ** t) % 10 * (t + 2)
        c = -s % 11
        if c == 10:
            c = "X"
        print(f"  sum {s}, check digit {c}")
    elif kind == "euclid":
        product = 1
        for p in nums:
            product = product * p
        n = product + 1
        d = 2
        while n % d != 0:
            d = d + 1
        print(f"  N = {n}, new prime {d}")
